public class AVAChargeSpecification extends common
{
}

Method.Source:
/// <summary>
/// finds a related chargeSpecification record
/// </summary>
/// <param name = "_accountCode">Account relation type</param>
/// <param name = "_accountRelation">Account relation value</param>
/// <param name = "_itemCode">Item relation type</param>
/// <param name = "_itemId">Item relation value</param>
/// <param name = "_chargeType">AVAChargeType</param>
/// <param name = "_fromDate">specified date, default today()</param>
/// <param name = "_selectForUpdate">default false</param>
/// <returns>AVAChargeSpecification</returns>
public static AVAChargeSpecification find(
    AVAAccountCode  _accountCode,
    CustVendRel     _accountRelation,
    AVAItemCode     _itemCode,
    ItemId          _itemId,
    AVAChargeType   _chargeType,
    FromDate        _fromDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
    boolean         _selectForUpdate = false)
{
    AVAChargeSpecification chargeSpecification;

    if(_selectForUpdate)
    {
        chargeSpecification.selectForUpdate(true);
    }

    select firstonly chargeSpecification
        order by chargeSpecification.FromDate desc
        where chargeSpecification.AccountCode   == _accountCode
        && chargeSpecification.AccountRelation  == _accountRelation
        && chargeSpecification.ItemCode         == _itemCode
        && chargeSpecification.ItemRelation     == _itemId
        && chargeSpecification.ChargeType       == _chargeType
        && (chargeSpecification.FromDate         <= _fromDate || !_fromDate);

    return chargeSpecification;
}

/// <summary>
/// init method for table <t>AVAChargeSpecification</t>
/// </summary>
public void initValue()
{
    super();

    PurchParameters purchParametersLoc = PurchParameters::find();

    this.CalculationUnit = purchParametersLoc.AVACharge_CalculationUnit;
    this.CurrencyCode = purchParametersLoc.AVACharge_CurrencyCode;
    this.FromDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    this.PriceUnit = 1;
}

/// <summary>
/// Displays related account name
/// </summary>
/// <returns>Name</returns>
[SysClientCacheDataMethod]
public display Name accountName()
{
    if(this.AccountCode == TableGroupAll::Table)
    {
        return this.vendTable().name();
    }
    else if(this.AccountCode == TableGroupAll::GroupId)
    {
        return this.markupGroup_Vend().Txt;
    }
    else
    {
        return '';
    }
}

/// <summary>
/// Displays related item name
/// </summary>
/// <returns>Name</returns>
[SysClientCacheDataMethod]
public display Name itemName()
{
    if(this.ItemCode == TableGroupAll::Table)
    {
        return this.inventTable().itemName();
    }
    else if(this.ItemCode == TableGroupAll::GroupId)
    {
        return this.markupGroup_Invent().Txt;
    }
    else
    {
        return '';
    }
}

/// <summary>
/// Returns vendor markup group
/// </summary>
/// <returns>MarkupGroup</returns>
public MarkupGroup markupGroup_Vend()
{
    MarkupGroup markupGroup;

    if(this.AccountCode == TableGroupAll::GroupId)
    {
        markupGroup = MarkupGroup::find(MarkupModuleType::Vend, this.AccountRelation);
    }

    return markupGroup;
}

/// <summary>
/// Returns invent markup group
/// </summary>
/// <returns>MarkupGroup</returns>
public MarkupGroup markupGroup_Invent()
{
    MarkupGroup markupGroup;

    if(this.ItemCode == TableGroupAll::GroupId)
    {
        markupGroup = MarkupGroup::find(MarkupModuleType::Invent, this.ItemRelation);
    }

    return markupGroup;
}

/// <summary>
/// Returns Vendor table
/// </summary>
/// <returns>VendTable</returns>
public VendTable vendTable()
{
    VendTable vendTable;

    if(this.AccountCode == TableGroupAll::Table)
    {
        vendTable = VendTable::find(this.AccountRelation);
    }

    return vendTable;
}

/// <summary>
/// Returns inventTable
/// </summary>
/// <returns>InventTable</returns>
public InventTable inventTable()
{
    return InventTable::find(this.ItemRelation);
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_priceDiscTable">_priceDiscTable</param>
/// <returns>AVAChargeSpecification</returns>
public static  AVAChargeSpecification findChargeSpecifTradeAgreement(PriceDiscTable       _priceDiscTable)
{
    AVAChargeSpecification          chargeSpecification;
    AVAAccountCode                  accountCode;
    AVAItemCode                     itemCode;
    ;

    switch (_priceDiscTable.AccountCode)
    {
        case PriceDiscPartyCodeType::All :
            accountCode = TableGroupAll::All;
            break;
        case PriceDiscPartyCodeType::GroupId :
            accountCode = TableGroupAll::GroupId;
            break;
        case PriceDiscPartyCodeType::Table :
            accountCode = TableGroupAll::Table;
            break;
        default: 
            break;
    }

    switch (_priceDiscTable.ItemCode)
    {
        case PriceDiscProductCodeType::All :
            itemCode = TableGroupAll::All;
            break;
        case PriceDiscProductCodeType::GroupId :
            itemCode = TableGroupAll::GroupId;
            break;
        case PriceDiscProductCodeType::Table :
            itemCode = TableGroupAll::Table;
            break;
        default: 
            break;
    }
    select firstonly chargeSpecification
        where chargeSpecification.AccountCode     == accountCode
           && chargeSpecification.AccountRelation == _priceDiscTable.AccountRelation
           && chargeSpecification.ItemCode        == itemCode
           && chargeSpecification.ItemRelation    == _priceDiscTable.ItemRelation
           && chargeSpecification.FromDate        <= _priceDiscTable.FromDate;

    return chargeSpecification;
}
